package com.roften.avilixlogger.compat.create;
import com.roften.avilixlogger.compat.create.mixin.*;
import com.roften.avilixlogger.core.*;
import com.simibubi.create.AllAttachmentTypes;
import com.simibubi.create.content.contraptions.OrientedContraptionEntity;
import com.simibubi.create.content.contraptions.minecart.capability.*;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.vehicle.AbstractMinecart;
import java.util.*;
/** Live bases and their full coupling graph form one endpoint of structural disassembly. */
public final class CreateCartRegistry {
    public static final String MUTATION="create/minecart/structural-mutation";
    private CreateCartRegistry(){}
    public static List<MinecartController> graph(MinecartController root){
        var found=new LinkedHashMap<UUID,MinecartController>();var pending=new ArrayDeque<MinecartController>();pending.add(root);
        while(!pending.isEmpty()){var controller=pending.removeFirst();var cart=controller.cart();if(cart==null||cart.isRemoved()||cart.level().isClientSide)throw new IllegalStateException("Участник сцепки отсутствует");if(found.putIfAbsent(cart.getUUID(),controller)!=null)continue;if(found.size()>256)throw new IllegalStateException("Граф сцепки превышает 256 вагонеток");
            for(boolean main:new boolean[]{true,false}){var id=controller.getCoupledCart(main);if(id==null)continue;var peer=CapabilityMinecartController.getIfPresent(cart.level(),id);if(peer==null||peer.isEmpty())throw new IllegalStateException("Участник сцепки выгружен");pending.add(peer);}}
        return List.copyOf(found.values());
    }
    public static CompoundTag snapshot(MinecartController controller){
        var cart=controller.cart();var tag=CreateCouplingAudit.data(controller);tag.putBoolean("Registered",CapabilityMinecartController.getIfPresent(cart.level(),cart.getUUID())==controller);tag.put("Base",CreateCartAudit.baseSnapshot(cart));var passengers=new ListTag();for(var entity:cart.getPassengers()){var value=new CompoundTag();value.putUUID("Id",entity.getUUID());passengers.add(value);}tag.put("Passengers",passengers);tag.put("Runtime",runtime(controller));return tag;
    }
    private static CompoundTag runtime(MinecartController controller){var cart=controller.cart();var tag=new CompoundTag();tag.putBoolean("Refresh",((MinecartRuntimeAccessor)controller).avilixlogger$refresh());tag.putBoolean("Leading",CapabilityMinecartController.loadedMinecartsWithCoupling.get(cart.level()).contains(cart.getUUID()));
        var additions=MinecartQueuesAccessor.avilixlogger$additions().get(cart.level());var unloads=MinecartQueuesAccessor.avilixlogger$unloads().get(cart.level());var added=new ArrayList<Integer>();var removed=new ArrayList<Integer>();for(int i=0;i<additions.size();i++)if(additions.get(i).getUUID().equals(cart.getUUID()))added.add(i);for(int i=0;i<unloads.size();i++)if(unloads.get(i).equals(cart.getUUID()))removed.add(i);tag.putIntArray("Additions",added);tag.putIntArray("Unloads",removed);return tag;}
    private static CompoundTag withoutController(CompoundTag base){var tag=base.copy();tag.getCompound("neoforge:attachments").remove("create:minecart_controller");return tag;}
    public static Set<UUID> validate(ListTag before,ListTag after,List<CreateStructuralRollbackPlan.Body> bodies){
        if(before.isEmpty()||before.size()>256||before.size()!=after.size())throw new IllegalStateException("Нет полного реестра вагонеток");var old=new CompoundTag();old.putInt("Format",2);old.putString("Kind","coupling");old.putBoolean("Complete",true);old.putUUID("Operation",new UUID(0,1));var next=old.copy();var oldCarts=new ListTag();var nextCarts=new ListTag();var seenBodies=new HashSet<UUID>();
        for(int i=0;i<before.size();i++){var a=before.getCompound(i);var z=after.getCompound(i);for(var tag:List.of(a,z)){
            if(!tag.getBoolean("Registered")||!tag.hasUUID("CartEntity")||!tag.contains("Base",10)||!tag.getCompound("Base").hasUUID("UUID")||!tag.getUUID("CartEntity").equals(tag.getCompound("Base").getUUID("UUID"))||!tag.getString("CartType").equals(tag.getCompound("Base").getString("id"))||!tag.contains("Passengers",9)||!tag.contains("Runtime",10))throw new IllegalStateException("Нет полного снимка базовой вагонетки");
            var state=tag.getCompound("Runtime");if(!state.contains("Refresh",1)||!state.contains("Leading",1)||!state.contains("Additions",11)||!state.contains("Unloads",11)||state.getIntArray("Additions").length>8192||state.getIntArray("Unloads").length!=0)throw new IllegalStateException("Нет рабочего реестра или база выгружается");int previous=-1;for(int index:state.getIntArray("Additions")){if(index<=previous)throw new IllegalStateException("Повреждена очередь регистрации базы");previous=index;}
            var list=tag.getList("Passengers",10);if(list.size()>1||tag.hasUUID("Construction")!=(list.size()==1)||list.size()==1&&(!list.getCompound(0).hasUUID("Id")||!list.getCompound(0).getUUID("Id").equals(tag.getUUID("ConstructionEntity"))))throw new IllegalStateException("Не все пассажиры вагонетки захвачены");
            var attachment=tag.getCompound("Base").getCompound("neoforge:attachments").getCompound("create:minecart_controller").copy();if(!attachment.getString("Type").equals("NORMAL"))throw new IllegalStateException("Непроверенный тип контроллера базы");attachment.remove("Type");if(!tag.getCompound("Native").equals(attachment))throw new IllegalStateException("Контроллер не совпадает с базовой вагонеткой");}
            if(!withoutController(a.getCompound("Base")).equals(withoutController(z.getCompound("Base"))))throw new IllegalStateException("Разборка изменила базу вне контроллера сцепки");var normalized=z.copy();
            if(a.hasUUID("ConstructionEntity")&&!z.hasUUID("ConstructionEntity")){var matches=bodies.stream().filter(body->body.before().getUUID("StorageEntity").equals(a.getUUID("ConstructionEntity"))).toList();if(matches.size()!=1)throw new IllegalStateException("Не сохранено разобранное тело сцепки");var body=matches.getFirst().before();var links=body.getList("Links",10);if(links.stream().map(raw->(CompoundTag)raw).filter(link->link.getString("Relation").equals("vehicle")&&link.hasUUID("Entity")&&link.getUUID("Entity").equals(a.getUUID("CartEntity"))).count()!=1)throw new IllegalStateException("Не сохранена связь тела с базой");for(String relation:List.of("coupled_main","coupled_connected"))if(links.stream().map(raw->(CompoundTag)raw).filter(link->link.getString("Relation").equals(relation)).count()!=(a.getCompound("Native").contains(relation.equals("coupled_main")?"MainCoupling":"ConnectedCoupling",10)?1:0))throw new IllegalStateException("Не сохранена связь тела со сцепкой");if(!body.getString("Dimension").equals(a.getString("Dimension"))||!body.getUUID("Construction").equals(a.getUUID("Construction"))||!seenBodies.add(a.getUUID("ConstructionEntity")))throw new IllegalStateException("Несвязанный участник разборки");for(String key:List.of("Construction","ConstructionEntity"))normalized.put(key,a.get(key).copy());}
            oldCarts.add(a.copy());nextCarts.add(normalized);}
        old.put("Carts",oldCarts);next.put("Carts",nextCarts);var plan=CreateCouplingRollbackPlan.prepare(old,next);
        for(var body:bodies)if(body.before().getString("ConstructionKind").equals("MINECART")&&!seenBodies.contains(body.before().getUUID("StorageEntity")))throw new IllegalStateException("Тело не связано с базой сцепки");return plan.constructions();
    }
    public static final class Endpoint {
        public final AbstractMinecart cart;final ServerLevel level;final MinecartController controller;final CompoundTag before,after;private CompoundTag compensationRuntime;
        public Endpoint(MinecraftServer server,CompoundTag before,CompoundTag after){this.before=before;this.after=after;AbstractMinecart found=null;for(var world:server.getAllLevels())if(world.getEntity(after.getUUID("CartEntity")) instanceof AbstractMinecart candidate){if(found!=null)throw new IllegalStateException("Повторный UUID базы");found=candidate;}if(found==null)throw new IllegalStateException("Базовая вагонетка отсутствует");cart=found;level=(ServerLevel)cart.level();controller=cart.getData(AllAttachmentTypes.MINECART_CONTROLLER);verify(false,false);if(cart instanceof net.minecraft.world.Container container)CartRestoreLocks.container(container);CartRestoreLocks.keepLoaded(level,cart.blockPosition());CartAuditContext.LOCKED_ENTITIES.add(cart.getUUID());var passenger=CreateCartAudit.passenger(cart);if(passenger!=null)CartAuditContext.LOCKED_ENTITIES.add(passenger.getUUID());}
        public void checkpoint(){verify(false,false);compensationRuntime=runtime(controller);}
        public void verify(boolean old,boolean exact){var expected=old?before:after;var actual=snapshot(controller);if(cart.isRemoved()||level.getEntity(cart.getUUID())!=cart||!level.hasChunkAt(cart.blockPosition())||cart.getData(AllAttachmentTypes.MINECART_CONTROLLER)!=controller||CapabilityMinecartController.getIfPresent(level,cart.getUUID())!=controller)throw new IllegalStateException("База или реестр сцепки изменены");var state=actual.getCompound("Runtime");actual.remove("Runtime");var saved=expected.copy();saved.remove("Runtime");if(!actual.equals(saved))throw new IllegalStateException("База, груз, пассажир или контроллер сцепки изменены");var expectedRuntime=old?before.getCompound("Runtime"):compensationRuntime;if(!exact&&state.getBoolean("Leading")!=controller.isLeadingCoupling()&&!state.getBoolean("Refresh")&&state.getIntArray("Additions").length==0)throw new IllegalStateException("Реестр ведущих баз изменён");if(exact&&(!Objects.equals(state.get("Refresh"),expectedRuntime.get("Refresh"))||!Objects.equals(state.get("Leading"),expectedRuntime.get("Leading"))||state.getIntArray("Additions").length!=expectedRuntime.getIntArray("Additions").length||state.getIntArray("Unloads").length!=expectedRuntime.getIntArray("Unloads").length))throw new IllegalStateException("Рабочий реестр сцепки не восстановлен");}
        public void set(boolean old){var tag=old?before:after;controller.deserializeNBT(level.registryAccess(),tag.getCompound("Native").copy());var passenger=CreateCartAudit.passenger(cart);if(passenger instanceof OrientedContraptionEntity oriented)oriented.setCouplingId(tag.hasUUID("CouplingId")?tag.getUUID("CouplingId"):null);CapabilityMinecartController.loadedMinecartsByUUID.get(level).put(cart.getUUID(),controller);var state=old?before.getCompound("Runtime"):compensationRuntime;
            ((MinecartRuntimeAccessor)controller).avilixlogger$refresh(state.getBoolean("Refresh"));var leading=CapabilityMinecartController.loadedMinecartsWithCoupling.get(level);if(state.getBoolean("Leading"))leading.add(cart.getUUID());else leading.remove(cart.getUUID());var additions=MinecartQueuesAccessor.avilixlogger$additions().get(level);var unloads=MinecartQueuesAccessor.avilixlogger$unloads().get(level);additions.removeIf(c->c.getUUID().equals(cart.getUUID()));unloads.removeIf(id->id.equals(cart.getUUID()));for(int i:state.getIntArray("Additions"))additions.add(Math.min(i,additions.size()),cart);for(int i:state.getIntArray("Unloads"))unloads.add(Math.min(i,unloads.size()),cart.getUUID());controller.sendData();if(!controller.serializeNBT(level.registryAccess()).equals(tag.getCompound("Native")))throw new IllegalStateException("Контроллер не прочитал полный NBT сцепки");}
    }
}
